text(S, "get_voting_configuration_name", {'configuration': 1}, "< GET 1 VOTING_CONFIGURATION_NAME >", device_reply="< REP 1 VOTING_CONFIGURATION_NAME {2-button voting                } >", expect_result={'ok': {'kind': 'value', 'value': '2-button voting'}})
telemetry(S, "voting_configuration_name", inbound="< REP 1 VOTING_CONFIGURATION_NAME {2-button voting                } >", expect_state={'voting': {'configurations': {'1': {'name': '2-button voting'}}}})
text(S, "get_voting_button_name", {'configuration': 1, 'button': 2}, "< GET 1 2 VOTING_BUTTON_NAME >", device_reply="< REP 1 2 VOTING_BUTTON_NAME {No                             } >", expect_result={'ok': {'kind': 'value', 'value': 'No'}})
telemetry(S, "voting-button-name", inbound="< REP 1 2 VOTING_BUTTON_NAME {No                             } >", expect_state={'voting': {'configurations': {'1': {'buttons': {'2': {'name': 'No'}}}}}})
text(S, "get_final_voting_selection", {'seat': 4}, "< GET 4 FINAL_VOTING_SELECTION >", device_reply="< REP 4 FINAL_VOTING_SELECTION 1 >", expect_result={'ok': {'kind': 'value', 'value': '1'}})
text(S, "get_final_voting_results", {}, "< GET 0 FINAL_VOTING_RESULT >", expect_result={'ok': {'kind': 'unverified'}})
telemetry(S, "interim-voting-selection", inbound="< REP 2 INTERIM_VOTING_SELECTION 5 >", expect_state={'voting': {'seats': {'2': {'interim_selection': 5}}}})
telemetry(S, "final-voting-selection", inbound="< REP 2 FINAL_VOTING_SELECTION 5 >", expect_state={'voting': {'seats': {'2': {'final_selection': 5}}}})
telemetry(S, "interim-voting-result", inbound="< REP 2 INTERIM_VOTING_RESULT 5 >", expect_state={'voting': {'buttons': {'2': {'interim_count': 5}}}})
telemetry(S, "final-voting-result", inbound="< REP 2 FINAL_VOTING_RESULT 5 >", expect_state={'voting': {'buttons': {'2': {'final_count': 5}}}})
telemetry(S, "results-shared", inbound="< REP SHARE_VOTING_RESULTS TRUE >", expect_state={'voting': {'results_shared': True}})
